# Out Here, Everything Breaks. We Test For That.

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock the contexts - we control the Wasteland
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: [{ id: '1', name: 'Guzzoline', price: 49.99 }],
    total: 49.99,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The Road to Confirmation', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'FURY-2024' });
  });

  // Helper - fill shipping. We go back. And test again.
  const fillShipping = async () => {
    await user.type(screen.getByLabelText(/street address/i), '123 Fury Road');
    await user.type(screen.getByLabelText(/city/i), 'Citadel');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
  };

  const fillPayment = async () => {
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Imperator Furiosa');
  };

  describe('Happy Path - Home. Green tests are home.', () => {
    it('completes full checkout flow', async () => {
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      await fillShipping();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      await fillPayment();
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/guzzoline/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('FURY-2024');
    });
  });

  describe('Validation - Finding weak points', () => {
    it('shows shipping errors for empty fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByText(/city is required/i)).toBeInTheDocument();
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'bad');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates card number is 16 digits', async () => {
      render(<Checkout />);
      await fillShipping();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      await user.type(screen.getByLabelText(/card number/i), '123');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit/i)).toBeInTheDocument();
    });
  });

  describe('Error States - Remember this edge case?', () => {
    it('displays payment failure and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      render(<Checkout />);

      await fillShipping();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await fillPayment();
      await user.click(screen.getByRole('button', { name: /review order/i }));
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });

      // Can retry
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'RETRY-001' });
      await user.click(screen.getByRole('button', { name: /place order/i }));
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
    });
  });

  describe('Loading States - The road is long', () => {
    it('disables buttons and shows loading during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      render(<Checkout />);

      await fillShipping();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await fillPayment();
      await user.click(screen.getByRole('button', { name: /review order/i }));
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  describe('Edge Cases - I have written unspeakable tests', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(require('./CartContext').useCart).mockReturnValue({
        items: [], total: 0, clearCart: mockClearCart
      });
      render(<Checkout />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Accessibility - Now I seek coverage', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });

    it('uses proper aria-invalid on invalid fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });
});
